class AllOne {
    private java.util.HashMap<String, Integer> keyCount;
    private java.util.TreeMap<Integer, java.util.LinkedHashSet<String>> countKeys;

    public AllOne() {
        keyCount = new java.util.HashMap<>();
        countKeys = new java.util.TreeMap<>();
    }

    public void inc(String key) {
        int oldCount = keyCount.getOrDefault(key, 0);
        int newCount = oldCount + 1;
        keyCount.put(key, newCount);
        if (oldCount > 0) {
            countKeys.get(oldCount).remove(key);
            if (countKeys.get(oldCount).isEmpty()) countKeys.remove(oldCount);
        }
        countKeys.computeIfAbsent(newCount, k -> new java.util.LinkedHashSet<>()).add(key);
    }

    public void dec(String key) {
        int oldCount = keyCount.get(key);
        int newCount = oldCount - 1;
        countKeys.get(oldCount).remove(key);
        if (countKeys.get(oldCount).isEmpty()) countKeys.remove(oldCount);
        if (newCount == 0) {
            keyCount.remove(key);
        } else {
            keyCount.put(key, newCount);
            countKeys.computeIfAbsent(newCount, k -> new java.util.LinkedHashSet<>()).add(key);
        }
    }

    public String getMaxKey() {
        if (countKeys.isEmpty()) return "";
        return countKeys.lastEntry().getValue().iterator().next();
    }

    public String getMinKey() {
        if (countKeys.isEmpty()) return "";
        return countKeys.firstEntry().getValue().iterator().next();
    }
}
